   330      const qint64 size = data.size();
   331      if (!prepareWriting(name, user, group, size, perm, atime, mtime, ctime)) {
   332          //qCWarning(KArchiveLog) << "prepareWriting failed";
   333          return false;
   334      }
   335
   336      // Write data
   337      // Note: if data is null, don't call write, it would terminate the KCompressionDevice
   338      if (data.constData() && size && !writeData(data.constData(), size)) {
   339          //qCWarning(KArchiveLog) << "writeData failed";
   340          return false;
   341      }
   342
   343      if (!finishWriting(size)) {
   344          //qCWarning(KArchiveLog) << "finishWriting failed";
   345          return false;
   346      }
   347      return true;
   348  }
