   350  bool KArchive::writeData(const char *data, qint64 size)
   351  {
   352      bool ok = device()->write(data, size) == size;
   353      if (!ok) {
   354          setErrorString(
   355              tr("Writing failed: %1")
   356              .arg(device()->errorString()));
   357          d->abortWriting();
   358      }
   359      return ok;
   360  }
