   792  const KArchiveEntry *KArchiveDirectory::entry(const QString &_name) const
   793  {
   794      QString name = QDir::cleanPath(_name);
   795      int pos = name.indexOf(QLatin1Char('/'));
   796      if (pos == 0) { // ouch absolute path (see also KArchive::findOrCreate)
   797          if (name.length() > 1) {
   798              name = name.mid(1);   // remove leading slash
   799              pos = name.indexOf(QLatin1Char('/'));   // look again
   800          } else { // "/"
   801              return this;
   802          }
   803      }
   804      // trailing slash ? -> remove
   805      if (pos != -1 && pos == name.length() - 1) {
   806          name = name.left(pos);
   807          pos = name.indexOf(QLatin1Char('/'));   // look again
   808      }
   809      if (pos != -1) {
   810          const QString left = name.left(pos);
   811          const QString right = name.mid(pos + 1);
   812
   813          //qCDebug(KArchiveLog) << "left=" << left << "right=" << right;
   814
   815          const KArchiveEntry *e = d->entries.value(left);
   816          if (!e || !e->isDirectory()) {
   817              return nullptr;
   818          }
   819          return static_cast<const KArchiveDirectory *>(e)->entry(right);
   820      }
